tr=lambda s:"".join(ct[s[i:i+3]] for i in range(0,len(s)-2,3))

def orfs(s,strand,minaa):
    res=[]; LL=len(s)
    for f in range(3):
        i=f
        while i<LL:
            if s[i:i+3]=='ATG':
                j=i
                while j<LL-2 and ct[s[j:j+3]]!='*': j+=3
                if j>LL-2: j=LL-3
                aa=(j-i)//3
                if aa>=minaa:
                    if strand=='+':
                        res.append((i+1,j+3,aa,'+',tr(s[i:j])))
                    else:
                        # convert rc coords to plus coords
                        a=L-(j+3)+1; b=L-i
                        res.append((a,b,aa,'-',tr(s[i:j])))
            i+=3
    return res

