L=len(seq)
comp = str.maketrans("ACGT","TGCA")
rc = lambda s: s.translate(comp)[::-1]

# long palindromes with longer loops
def hairpins(min_stem, max_loop):
    out=[]
    for i in range(L):
        for st in range(min_stem,60):
            for lp in range(1,max_loop+1):
                j=i+st+lp
                if j+st>L: break
                if seq[i:i+st]==rc(seq[j:j+st]):
                    out.append((i+1,j+st,st,lp))
    return out
hp=hairpins(10,60)
seen=set(); u=[]
for x in sorted(hp,key=lambda z:(-z[2],z[3])):
    k=(x[0],x[2])
    if k in seen:continue
    seen.add(k); u.append(x)
print("hairpins stem>=10:", u[:20])

